// Generates the Rust Unicode data tables used by the javac port from the
// running JDK (must be JDK 17). The generated file is checked into the repo so
// that building rust-javac never requires a JVM; run it through
// "cargo xtask gen-unicode" when upgrading the JDK baseline.
//
// Usage: java GenUnicode.java <output-rust-file> [oracle-file]
//
// The optional oracle file is the development-time, full-table oracle for
// javac-unicode: for each ported Character predicate it records the FNV-1a 64
// hash of the predicate over every code point MIN_CODE_POINT..=MAX_CODE_POINT
// (one hash bit per code point). The integration test re-computes the hashes
// from the ported tables at test time (no JVM needed).

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

public class GenUnicode {
    interface Prop {
        boolean test(int cp);
    }

    static final int MAX = 0x10FFFF;
    static final StringBuilder out = new StringBuilder();

    public static void main(String[] args) throws Exception {
        if (args.length < 1 || args.length > 2) {
            System.err.println("usage: java GenUnicode.java <output-rust-file> [oracle-file]");
            System.exit(2);
        }
        out.append("// GENERATED by tools/gen-unicode/GenUnicode.java via the gen-unicode xtask.\n");
        out.append("// Data source: the running JDK 17 java.lang.Character (Unicode data).\n");
        out.append("// DO NOT EDIT.\n\n");

        emitRanges("JAVA_ID_START", Character::isJavaIdentifierStart);
        emitRanges("JAVA_ID_PART", Character::isJavaIdentifierPart);
        emitRanges("UNICODE_ID_START", Character::isUnicodeIdentifierStart);
        emitRanges("UNICODE_ID_PART", Character::isUnicodeIdentifierPart);
        emitRanges("WHITESPACE", Character::isWhitespace);
        emitRanges("SPACE_CHAR", Character::isSpaceChar);
        emitRanges("DEFINED", Character::isDefined);
        emitRanges("DIGIT", Character::isDigit);
        emitRanges("IDENTIFIER_IGNORABLE", Character::isIdentifierIgnorable);

        emitDigitValues();
        emitCaseMap("LOWER_CASE", Character::toLowerCase);
        emitCaseMap("UPPER_CASE", Character::toUpperCase);

        Files.writeString(Path.of(args[0]), out.toString(), StandardCharsets.UTF_8);
        System.out.println("gen-unicode: wrote " + args[0] + " (" + out.length() + " chars)");

        if (args.length == 2) {
            StringBuilder oracle = new StringBuilder();
            oracle.append("# char-oracle-v1\n");
            oracle.append("# Developed from the JDK 17 java.lang.Character int overloads over\n");
            oracle.append("# code points 0x000000..=0x10FFFF; FNV-1a 64 over one bit per code point.\n");
            emitOracle(oracle, "JAVA_ID_START", Character::isJavaIdentifierStart);
            emitOracle(oracle, "JAVA_ID_PART", Character::isJavaIdentifierPart);
            emitOracle(oracle, "UNICODE_ID_START", Character::isUnicodeIdentifierStart);
            emitOracle(oracle, "UNICODE_ID_PART", Character::isUnicodeIdentifierPart);
            emitOracle(oracle, "WHITESPACE", Character::isWhitespace);
            emitOracle(oracle, "IDENTIFIER_IGNORABLE", Character::isIdentifierIgnorable);
            Files.writeString(Path.of(args[1]), oracle.toString(), StandardCharsets.UTF_8);
            System.out.println("gen-unicode: wrote " + args[1] + " (" + oracle.length() + " chars)");
        }
    }

    static void emitOracle(StringBuilder oracle, String name, Prop p) {
        long hash = 0xcbf29ce484222325L;
        for (int cp = 0; cp <= MAX; cp++) {
            hash ^= p.test(cp) ? 1L : 0L;
            hash *= 0x100000001b3L;
        }
        oracle.append(name).append(" 0x").append(Long.toHexString(hash)).append("\n");
    }

    static void emitRanges(String name, Prop p) {
        out.append("pub static ").append(name).append(": &[(u32, u32)] = &[\n");
        int start = -1;
        for (int cp = 0; cp <= MAX; cp++) {
            boolean v = p.test(cp);
            if (v && start < 0) {
                start = cp;
            } else if (!v && start >= 0) {
                appendRange(start, cp - 1);
                start = -1;
            }
        }
        if (start >= 0) {
            appendRange(start, MAX);
        }
        out.append("];\n\n");
    }

    static void appendRange(int start, int end) {
        out.append("    (0x").append(Integer.toHexString(start)).append(", 0x")
                .append(Integer.toHexString(end)).append("),\n");
    }

    // Java's Character.digit(cp, radix) must equal digit36 < radix ? digit36 : -1;
    // verify that contract for every code point and radix before emitting the table.
    static void emitDigitValues() {
        for (int cp = 0; cp <= MAX; cp++) {
            int d36 = Character.digit(cp, 36);
            for (int radix = 2; radix <= 36; radix++) {
                int expected = (d36 >= 0 && d36 < radix) ? d36 : -1;
                int actual = Character.digit(cp, radix);
                if (actual != expected) {
                    System.err.println("digit contract violated for cp=0x" + Integer.toHexString(cp)
                            + " radix=" + radix + ": expected " + expected + " actual " + actual);
                    System.exit(1);
                }
            }
        }
        out.append("pub static DIGIT_VALUES: &[(u32, u8)] = &[\n");
        for (int cp = 0; cp <= MAX; cp++) {
            int d = Character.digit(cp, 36);
            if (d >= 0) {
                out.append("    (0x").append(Integer.toHexString(cp)).append(", ").append(d).append("),\n");
            }
        }
        out.append("];\n\n");
    }

    interface CaseFn {
        int apply(int cp);
    }

    static void emitCaseMap(String name, CaseFn f) {
        out.append("pub static ").append(name).append(": &[(u32, u32)] = &[\n");
        for (int cp = 0; cp <= MAX; cp++) {
            int mapped = f.apply(cp);
            if (mapped != cp) {
                out.append("    (0x").append(Integer.toHexString(cp)).append(", 0x")
                        .append(Integer.toHexString(mapped)).append("),\n");
            }
        }
        out.append("];\n\n");
    }
}
